def time_to_reach_destination(x1, y1, x2, y2, v_max, t, wind1, wind2):
    def distance(x1, y1, x2, y2):
        return math.sqrt((x2 - x1) ** 2 + (y2 - y1) ** 2)

    def dot_product(v1, v2):
        return v1[0] * v2[0] + v1[1] * v2[1]

    def vector_subtract(v1, v2):
        return (v1[0] - v2[0], v1[1] - v2[1])

    def vector_length(v):
        return math.sqrt(v[0] ** 2 + v[1] ** 2)

    def normalize(v):
        length = vector_length(v)
        return (v[0] / length, v[1] / length)

    def time_to_reach_with_wind(start, end, wind, v_max):
        relative_vector = vector_subtract(end, start)
        wind_effect = dot_product(relative_vector, wind)
        if wind_effect >= 0:
            return distance(start[0], start[1], end[0], end[1]) / v_max
        else:
            wind_speed = vector_length(wind)
            wind_direction = normalize(wind)
            perp_vector = (-wind_direction[1], wind_direction[0])
            perp_effect = dot_product(relative_vector, perp_vector)
            if perp_effect == 0:
                return distance(start[0], start[1], end[0], end[1]) / v_max
            else:
                time_to_perp = abs(perp_effect) / (v_max ** 2)
                distance_to_perp = abs(wind_effect) / v_max
                return time_to_perp + distance_to_perp

    start = (x1, y1)
    end = (x2, y2)

    time_first_phase = time_to_reach_with_wind(start, end, wind1, v_max)
    time_second_phase = time_to_reach_with_wind(end, end, wind2, v_max)

    return time_first_phase + time_second_phase

