def min_time_to_destination(x1, y1, x2, y2, v_max, t, wind1, wind2):
    def distance(x1, y1, x2, y2):
        return math.sqrt((x2 - x1) ** 2 + (y2 - y1) ** 2)

    def wind_at_time(seconds):
        if seconds < t:
            return wind1
        else:
            return wind2

    def heuristic(x, y):
        return distance(x, y, x2, y2)

    def get_neighbors(x, y, vx, vy, seconds):
        neighbors = []
        wind = wind_at_time(seconds)
        wind_x, wind_y = wind
        # Calculate new position considering wind
        new_x = x + wind_x
        new_y = y + wind_y
        # Calculate speed
        speed = math.sqrt(vx ** 2 + vy ** 2)
        if speed > v_max:
            vx = (vx / speed) * v_max
            vy = (vy / speed) * v_max
        # Possible directions: continue in the same direction, change direction
        directions = [(vx, vy), (-vx, vy), (vx, -vy), (-vx, -vy)]
        for dx, dy in directions:
            if dx == 0 and dy == 0:
                continue
            new_speed = math.sqrt(dx ** 2 + dy ** 2)
            if new_speed > v_max:
                dx = (dx / new_speed) * v_max
                dy = (dy / new_speed) * v_max
            neighbors.append((new_x, new_y, dx, dy, seconds + 1))
        return neighbors

    # Priority queue for A* search
    open_set = []
    heappush(open_set, (0, x1, y1, 0, 0, 0))  # (priority, x, y, vx, vy, time)
    g_score = {(x1, y1, 0, 0): 0}

    while open_set:
        _, x, y, vx, vy, time = heappop(open_set)

